204: impl DispatchError {
205:     /// Attempt to decode a runtime [`DispatchError`].
206:     #[doc(hidden)]
207:     pub fn decode_from<'a>(
208:         bytes: impl Into<Cow<'a, [u8]>>,
209:         metadata: Metadata,
210:     ) -> Result<Self, super::Error> {
211:         let bytes = bytes.into();
212:         let dispatch_error_ty_id = metadata
213:             .dispatch_error_ty()
214:             .ok_or(MetadataError::DispatchErrorNotFound)?;
215: 
216:         // The aim is to decode our bytes into roughly this shape. This is copied from
217:         // `sp_runtime::DispatchError`; we need the variant names and any inner variant
218:         // names/shapes to line up in order for decoding to be successful.
219:         #[derive(scale_decode::DecodeAsType)]
220:         enum DecodedDispatchError {
221:             Other,
222:             CannotLookup,
223:             BadOrigin,
224:             Module(DecodedModuleErrorBytes),
225:             ConsumerRemaining,
226:             NoProviders,
227:             TooManyConsumers,
228:             Token(TokenError),
229:             Arithmetic(ArithmeticError),
230:             Transactional(TransactionalError),
231:             Exhausted,
232:             Corruption,
233:             Unavailable,
234:         }
235: 
236:         // ModuleError is a bit special; we want to support being decoded from either
237:         // a legacy format of 2 bytes, or a newer format of 5 bytes. So, just grab the bytes
238:         // out when decoding to manually work with them.
239:         struct DecodedModuleErrorBytes(Vec<u8>);
240:         struct DecodedModuleErrorBytesVisitor;
241:         impl scale_decode::Visitor for DecodedModuleErrorBytesVisitor {
242:             type Error = scale_decode::Error;
243:             type Value<'scale, 'info> = DecodedModuleErrorBytes;
244:             fn unchecked_decode_as_type<'scale, 'info>(
245:                 self,
246:                 input: &mut &'scale [u8],
247:                 _type_id: scale_decode::visitor::TypeId,
248:                 _types: &'info scale_info::PortableRegistry,
249:             ) -> DecodeAsTypeResult<Self, Result<Self::Value<'scale, 'info>, Self::Error>>
250:             {
251:                 DecodeAsTypeResult::Decoded(Ok(DecodedModuleErrorBytes(input.to_vec())))
252:             }
253:         }
254:         impl scale_decode::IntoVisitor for DecodedModuleErrorBytes {
255:             type Visitor = DecodedModuleErrorBytesVisitor;
256:             fn into_visitor() -> Self::Visitor {
257:                 DecodedModuleErrorBytesVisitor
258:             }
259:         }
260: 
261:         // Decode into our temporary error:
262:         let decoded_dispatch_err = DecodedDispatchError::decode_with_metadata(
263:             &mut &*bytes,
264:             dispatch_error_ty_id,
265:             &metadata,
266:         )?;
267: 
268:         // Convert into the outward-facing error, mainly by handling the Module variant.
269:         let dispatch_error = match decoded_dispatch_err {
270:             // Mostly we don't change anything from our decoded to our outward-facing error:
271:             DecodedDispatchError::Other => DispatchError::Other,
272:             DecodedDispatchError::CannotLookup => DispatchError::CannotLookup,
273:             DecodedDispatchError::BadOrigin => DispatchError::BadOrigin,
274:             DecodedDispatchError::ConsumerRemaining => DispatchError::ConsumerRemaining,
275:             DecodedDispatchError::NoProviders => DispatchError::NoProviders,
276:             DecodedDispatchError::TooManyConsumers => DispatchError::TooManyConsumers,
277:             DecodedDispatchError::Token(val) => DispatchError::Token(val),
278:             DecodedDispatchError::Arithmetic(val) => DispatchError::Arithmetic(val),
279:             DecodedDispatchError::Transactional(val) => DispatchError::Transactional(val),
280:             DecodedDispatchError::Exhausted => DispatchError::Exhausted,
281:             DecodedDispatchError::Corruption => DispatchError::Corruption,
282:             DecodedDispatchError::Unavailable => DispatchError::Unavailable,
283:             // But we apply custom logic to transform the module error into the outward facing version:
284:             DecodedDispatchError::Module(module_bytes) => {
285:                 let module_bytes = module_bytes.0;
286: 
287:                 // The old version is 2 bytes; a pallet and error index.
288:                 // The new version is 5 bytes; a pallet and error index and then 3 extra bytes.
289:                 let raw = if module_bytes.len() == 2 {
290:                     RawModuleError {
291:                         bytes: [module_bytes[0], module_bytes[1], 0, 0, 0],
292:                     }
293:                 } else if module_bytes.len() == 5 {
294:                     RawModuleError {
295:                         bytes: [
296:                             module_bytes[0],
297:                             module_bytes[1],
298:                             module_bytes[2],
299:                             module_bytes[3],
300:                             module_bytes[4],
301:                         ],
302:                     }
303:                 } else {
304:                     tracing::warn!("Can't decode error sp_runtime::DispatchError: bytes do not match known shapes");
305:                     // Return _all_ of the bytes; every "unknown" return should be consistent.
306:                     return Err(super::Error::Unknown(bytes.to_vec()));
307:                 };
308: 
309:                 // And return our outward-facing version:
310:                 DispatchError::Module(ModuleError { metadata, raw })
311:             }
312:         };
313: 
314:         Ok(dispatch_error)
315:     }
316: }

